<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_once __DIR__.'/../includes/Exporter.php';
$user=require_login();$workspace=require_workspace();$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$format=(string)($_GET['format']??'csv');if(!in_array($format,['csv','xlsx'],true)){http_response_code(400);exit('Format tidak didukung.');}if($format==='xlsx'&&!plan_limits($workspace)['exports']){http_response_code(403);exit('Ekspor Excel tersedia pada Pro atau Business; CSV tetap tersedia pada Free.');}$st=$GLOBALS['pdo']->prepare('SELECT id,name,row_count FROM datasets WHERE id=? AND workspace_id=? LIMIT 1');$st->execute([$id,$workspace['id']]);$dataset=$st->fetch();if(!$dataset){http_response_code(404);exit('Dataset tidak ditemukan.');}$st=$GLOBALS['pdo']->prepare('SELECT column_name FROM dataset_columns WHERE dataset_id=? ORDER BY ordinal');$st->execute([$id]);$headers=$st->fetchAll(PDO::FETCH_COLUMN);$search=mb_substr(trim((string)($_GET['q']??'')),0,200,'UTF-8');$sql='SELECT row_json FROM dataset_rows WHERE dataset_id=?';$params=[(int)$id];if($search!==''){$escaped=str_replace(['!','%','_'],['!!','!%','!_'],$search);$sql.=" AND row_json LIKE ? ESCAPE '!'";$params[]='%'.$escaped.'%';}$sql.=' ORDER BY `row_number` LIMIT 10000';$st=$GLOBALS['pdo']->prepare($sql);$st->execute($params);$rows=[];while($raw=$st->fetchColumn()){$row=json_decode((string)$raw,true);if(is_array($row))$rows[]=$row;}$GLOBALS['pdo']->prepare('INSERT INTO usage_logs(workspace_id,user_id,usage_type,units,month_key,metadata_json) VALUES(?,? ,"export",1,?,?)')->execute([$workspace['id'],$user['id'],date('Y-m'),json_encode(['dataset_id'=>(int)$id,'format'=>$format,'rows'=>count($rows)])]);audit_log('dataset.exported','dataset',(int)$id,['format'=>$format,'rows'=>count($rows)]);$filename='datanix-'.slugify((string)$dataset['name']);if($format==='xlsx')DatanixExporter::xlsx($headers,$rows,$filename.'.xlsx');DatanixExporter::csv($headers,$rows,$filename.'.csv');
